import unittest
from format_literals import *
class FormatLiterals(unittest.TestCase):
    def test_literal_format_codes(self):
        rows=[('oak%nleaf','oak\nleaf'),('done=100%%','done=100%'),('a%x2Cb%x29','a,b)'),('a%x00b','a\x00b'),('%%n','%n'),('%x25n','%n'),('%%%n','%\n'),('%x0A%x09','\n\t'),('%x41f','Af'),('%x0a%x7f','\n\x7f'),('oak','oak'),('','')]
        for template,expected in rows:
            with self.subTest(template=template):
                self.assertEqual(render_literals(template),expected)

    def test_all_ascii_hex_codes(self):
        for value in range(128):
            with self.subTest(value=value):
                self.assertEqual(render_literals('%x' + format(value, '02x')), chr(value))

if __name__ == '__main__':
    unittest.main()

