def render_literals(template):
    result = []
    index = 0
    while index < len(template):
        if template[index:index+2] == '%%':
            result.append('%')
            index += 2
        elif template[index:index+2] == '%n':
            result.append('\n')
            index += 2
        elif template[index:index+2] == '%x':
            result.append(chr(int(template[index+2:index+4], 16)))
            index += 4
        else:
            result.append(template[index])
            index += 1
    return ''.join(result)
